import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"CLI コマンド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/cli/overview.md","filePath":"ja/cli/overview.md","lastUpdated":1784903584000}'),a={name:"ja/cli/overview.md"};function r(l,e,i,s,n,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="cli-コマンド" tabindex="-1">CLI コマンド <a class="header-anchor" href="#cli-コマンド" aria-label="Permalink to &quot;CLI コマンド&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p><code>swag2mcp</code> CLI は、すべての操作の単一エントリポイントです — ワークスペースの初期化や API 仕様の管理から、LLM 統合のための MCP サーバーの起動まで。OpenAPI/Swagger/Postman の spec を扱う完全なライフサイクルをカバーする <strong>13 のコマンド</strong> を提供します。</p><h3 id="cli-が解決するもの" tabindex="-1">CLI が解決するもの <a class="header-anchor" href="#cli-が解決するもの" aria-label="Permalink to &quot;CLI が解決するもの&quot;">​</a></h3><ul><li><strong>ワークスペースライフサイクル</strong> — 作成（<code>init</code>）、検査（<code>info</code>、<code>ls</code>）、クリーンアップ（<code>clean</code>）、更新（<code>update</code>）、削除（<code>delete</code>）</li><li><strong>Spec と Collection の管理</strong> — API 仕様とその collection の追加（<code>add</code>）、一覧表示（<code>ls</code>）、削除（<code>delete</code>）</li><li><strong>実行モード</strong> — LLM ツールアクセス用の MCP サーバー起動（<code>mcp</code>）、または対話型 TUI エクスプローラー起動（<code>run</code>）</li><li><strong>診断</strong> — 設定の検証（<code>validate</code>）、バージョン表示（<code>version</code>）、ランタイム情報表示（<code>info</code>）</li><li><strong>バックアップと復元</strong> — ZIP による完全なワークスペースラウンドトリップ（<code>export</code>、<code>import</code>）</li></ul><h3 id="主要なニュアンス" tabindex="-1">主要なニュアンス <a class="header-anchor" href="#主要なニュアンス" aria-label="Permalink to &quot;主要なニュアンス&quot;">​</a></h3><ul><li><strong>パス解決</strong> — <code>[path]</code> を受け付けるコマンドは<strong>ワークスペースディレクトリ</strong>（ファイルパスではない）を期待します。解決順序：明示的な <code>[path]</code> → カレントディレクトリ（<code>./</code>）→ <code>~/.swag2mcp/</code>。CLI は自動的に <code>swag2mcp.yaml</code> を追加します。サービスとして実行する場合や IDE 設定では、間違ったワークスペースを読み込まないよう常に明示的なパスを渡してください。</li><li><strong>Spec と Collection の違い</strong> — <strong>spec</strong> は論理的な API サービス（例：「Open-Meteo API」）を表し、<strong>collection</strong> は 1 つの OpenAPI/Swagger/Postman ファイルです。1 つの spec は複数の collection を持つことができます。</li><li><strong><code>--version</code></strong> はフラグ（<code>swag2mcp --version</code>）とサブコマンド（<code>swag2mcp version</code>）の両方としてサポートされています。</li><li><strong><code>add spec</code> / <code>add collection</code></strong> は <code>--yaml</code>（インライン文字列または標準入力の <code>-</code>）を介して YAML 入力を受け付けます。ファイルまたはヒアドキュメントからのパイプは、特殊文字によるシェルの引用符問題を回避します。</li><li><strong><code>delete</code></strong> は TTY（対話型ターミナル）が必要です。<code>--force</code> や <code>--yes</code> フラグはありません — 常に選択と確認を促します。</li><li><strong><code>mcp</code></strong> は LLM 統合の主要コマンドです。3 つのトランスポートをサポート：<code>stdio</code>（デフォルト）、<code>sse</code>、<code>streamable-http</code>。<code>--disable-llm-auth</code> フラグ（デフォルト：<code>true</code>）は MCP ツールリストから <code>auth</code> ツールを削除し、LLM がトークンを表示したり要求したりするのを防ぎます。認証は引き続き機能します — トークンは LLM 経由ではなく、標準の設定メカニズムを通じて取得されます。このモードは<strong>本番環境</strong>に推奨されます（LLM は認証情報にアクセスできません）。<strong>デバッグ</strong>や短命トークンを使用する場合は、<code>--disable-llm-auth=false</code> を設定して LLM が <code>auth</code> ツールを介して新しいトークンを要求できるようにします。</li><li><strong><code>validate</code></strong> は YAML 構文、設定構造、spec ファイルの存在、URL の到達可能性、spec 形式（OpenAPI/Swagger/Postman）、認証設定、HTTP クライアントの正確性をチェックします。認証エンドポイントや API エンドポイントの可用性は<strong>テストしません</strong>。</li><li><strong><code>export</code> / <code>import</code></strong> は完全なワークスペースラウンドトリップを提供します — 設定ファイル、spec ファイル、キャッシュ、認証スクリプトがすべて ZIP アーカイブに含まれます。</li><li><strong><code>clean</code></strong> は <code>cache/</code> と <code>responses/</code> ディレクトリを削除しますが、<code>specs/</code> と <code>auth_scripts/</code> は保持します。古いレスポンス（48 時間以上）は <code>mcp</code> 起動時に自動的にクリーンアップされます。</li></ul><h2 id="コマンド一覧" tabindex="-1">コマンド一覧 <a class="header-anchor" href="#コマンド一覧" aria-label="Permalink to &quot;コマンド一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>コマンド</th><th>説明</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>デフォルト設定でワークスペースディレクトリを初期化</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>設定に spec または collection を追加</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>対話的に spec または collection を削除</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>すべての spec とその collection を一覧表示</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>対話型 TUI API エクスプローラーを起動</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>設定と spec ファイルを検証</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>キャッシュされた spec と呼び出しレスポンスをクリア</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>すべての spec を再検証、再キャッシュ、再インデックス化</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>LLM ツールアクセス用の MCP サーバーを起動</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>swag2mcp バージョンを表示</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>詳細な設定とランタイム情報を表示</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>spec ファイルをインポート、または ZIP からワークスペースを復元</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>ワークスペースをポータブルな ZIP バックアップとしてエクスポート</td></tr></tbody></table><h2 id="グローバルフラグ" tabindex="-1">グローバルフラグ <a class="header-anchor" href="#グローバルフラグ" aria-label="Permalink to &quot;グローバルフラグ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フラグ</th><th>説明</th></tr></thead><tbody><tr><td><code>--version</code></td><td>バージョンを表示（<code>version</code> サブコマンドと同じ）</td></tr><tr><td><code>--help</code></td><td>任意のコマンドのヘルプを表示</td></tr></tbody></table>',11)])])}const m=o(a,[["render",r]]);export{g as __pageData,m as default};
